from heapq import heappush, heappop

def longestDiverseString(a, b, c):
    # Create a max heap to prioritize characters with the most occurrences
    heap = []
    if a > 0: heappush(heap, (-a, 'a'))
    if b > 0: heappush(heap, (-b, 'b'))
    if c > 0: heappush(heap, (-c, 'c'))

    result = []
    while heap:
        count, char = heappop(heap)
        if len(result) >= 2 and result[-1] == char and result[-2] == char:
            if not heap:
                break
            next_count, next_char = heappop(heap)
            result.append(next_char)
            next_count += 1
            if next_count < 0:
                heappush(heap, (next_count, next_char))
            heappush(heap, (count, char))
        else:
            result.append(char)
            count += 1
            if count < 0:
                heappush(heap, (count, char))

    return ''.join(result)

# Example usage:
# print(longestDiverseString(1, 1, 7))  # Output: "ccaccbcc"
# print(longestDiverseString(2, 2, 1))  # Output: "aabbc"
# print(longestDiverseString(7, 1, 0))  # Output: "aabaa"
```

This function uses a max heap to prioritize the characters with the most occurrences. It then constructs the longest happy string by always appending the most frequent character unless it would violate the condition of not having 'aaa', 'bbb', or 'ccc' as substrings. If appending the most frequent character would violate this condition, it appends the next most frequent character instead, ensuring that the string remains happy.

